const db = global.get("db");
const crypto = global.get("crypto");
const body = msg.payload || {};

const deny = () => [{ payload: { cmd: "DENY" } }, null];

const combinedMethod = (type) =>
    type === "rfid" ? "RFID + PIN" : "BLE + PIN";

const safeKey = (value) =>
    String(value).trim().toUpperCase().replace(/[.#$[\]\/]/g, "_");

let userId = null;
let username = null;
let method = null;

// =========================
// 1. Xác thực OTP từ ESP32
// =========================
if (body.type === "otp") {
    const code = String(body.value || body.code || "");

    if (!/^\d{6}$/.test(code)) {
        node.warn("[verify] DENY - OTP phải có 6 chữ số");
        return deny();
    }

    const usersSnap = await db.ref("users").once("value");
    const users = [];

    usersSnap.forEach((child) => {
        users.push({
            id: child.key,
            data: child.val()
        });
    });

    const base32ToBuffer = (secret) => {
        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
        let bits = "";
        const bytes = [];

        for (const char of String(secret).replace(/=+$/, "").toUpperCase()) {
            const index = chars.indexOf(char);
            if (index >= 0) {
                bits += index.toString(2).padStart(5, "0");
            }
        }

        for (let i = 0; i + 8 <= bits.length; i += 8) {
            bytes.push(parseInt(bits.slice(i, i + 8), 2));
        }

        return Buffer.from(bytes);
    };

    const makeTotp = (secret, counter) => {
        const data = Buffer.alloc(8);

        data.writeUInt32BE(
            Math.floor(counter / 0x100000000),
            0
        );

        data.writeUInt32BE(
            counter >>> 0,
            4
        );

        const hash = crypto
            .createHmac("sha1", base32ToBuffer(secret))
            .update(data)
            .digest();

        const offset = hash[hash.length - 1] & 15;

        const number =
            ((hash[offset] & 127) << 24) |
            (hash[offset + 1] << 16) |
            (hash[offset + 2] << 8) |
            hash[offset + 3];

        return String(number % 1000000).padStart(6, "0");
    };

    const currentCounter = Math.floor(Date.now() / 30000);
    let matched = null;

    for (const user of users) {
        const twofaSnap = await db
            .ref("twofa/" + user.id)
            .once("value");

        twofaSnap.forEach((child) => {
            const account = child.val();

            for (let offset = -1; offset <= 1; offset++) {
                if (
                    account &&
                    account.secret &&
                    makeTotp(
                        account.secret,
                        currentCounter + offset
                    ) === code
                ) {
                    matched = user;
                }
            }
        });

        if (matched) break;
    }

    if (!matched) {
        node.warn("[verify] DENY - OTP không hợp lệ");
        return deny();
    }

    userId = matched.id;
    username = matched.data.username;
    method = "2FA OTP";
}

// ======================================
// 2. Các phương thức credential khác
// ======================================
else {
    const lookupSnap = await db
        .ref(
            "credential_lookup/" +
            body.type +
            "/" +
            safeKey(body.value)
        )
        .once("value");

    if (!lookupSnap.exists()) {
        node.warn(
            "[verify] DENY - không tìm thấy credential: " +
            body.type
        );
        return deny();
    }

    const credSnap = await db
        .ref("credentials/" + lookupSnap.val())
        .once("value");

    const credential = credSnap.val();

    if (!credential) {
        return deny();
    }

    const userSnap = await db
        .ref("users/" + credential.user_id)
        .once("value");

    const user = userSnap.val();

    if (!user) {
        return deny();
    }

    userId = credential.user_id;
    username = user.username;

    const pendingRef = db.ref("pending_auth/" + userId);
    const pendingSnap = await pendingRef.once("value");
    const pending = pendingSnap.val();

    const isFresh =
        pending &&
        Date.now() - Number(pending.created_at || 0) <= 30000;

    // Fingerprint mở cửa độc lập
    if (body.type === "fingerprint") {
        method = "Fingerprint";
    }

    // RFID/BLE chỉ tạo bước chờ PIN
    else if (body.type === "rfid" || body.type === "ble") {
        if (isFresh && pending.method === "pin") {
            method = combinedMethod(body.type);
            await pendingRef.remove();
        } else {
            await pendingRef.set({
                user_id: userId,
                username: username,
                method: body.type,
                created_at: Date.now()
            });

            node.warn(
                "[verify] Đã nhận " +
                body.type +
                ", đang chờ PIN"
            );

            return [null, null];
        }
    }

    // PIN bắt buộc phải đi sau RFID/BLE
    else if (body.type === "pin") {
        const hasOtherMethod =
            isFresh &&
            pending &&
            (pending.method === "rfid" ||
                pending.method === "ble") &&
            pending.user_id === userId;

        if (!hasOtherMethod) {
            node.warn(
                "[verify] DENY - PIN không đi kèm RFID/BLE"
            );

            return [{ payload: { cmd: "DENY" } }, null];
        }

        method = combinedMethod(pending.method);
        await pendingRef.remove();
    }

    else {
        return deny();
    }
}

